import { Suspense, ViewTransition } from 'react'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'

export default function Home() {
  return (
    <main>
      <ViewTransition
        enter={{
          'nav-forward': 'nav-forward',
          'nav-back': 'nav-back',
          default: 'none',
        }}
        exit={{
          'nav-forward': 'nav-forward',
          'nav-back': 'nav-back',
          default: 'none',
        }}
        default="none"
      >
        <h1>Products</h1>
        <Suspense
          fallback={
            <ViewTransition exit="skeleton-exit">
              <ProductGridSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="skeleton-enter" default="none">
            <ProductGrid />
          </ViewTransition>
        </Suspense>
      </ViewTransition>
    </main>
  )
}

