@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* View transitions — durations */
:root {
  --vt-duration-exit: 150ms;
  --vt-duration-enter: 210ms;
  --vt-slide-distance: 60px;
}

/* Shared product image: thumbnail ↔ hero morph */
::view-transition-group(.morph) {
  animation-duration: 400ms;
}

::view-transition-image-pair(.morph) {
  animation-name: vt-morph-blur;
}

@keyframes vt-morph-blur {
  30% {
    filter: blur(3px);
  }
}

/* Directional route transitions */
@keyframes vt-fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes vt-slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

::view-transition-old(.nav-forward) {
  --slide-offset: calc(var(--vt-slide-distance) * -1);
  animation:
    var(--vt-duration-exit) ease-in both vt-fade reverse,
    400ms ease-in-out both vt-slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: var(--vt-slide-distance);
  animation:
    var(--vt-duration-enter) ease-out var(--vt-duration-exit) both vt-fade,
    400ms ease-in-out both vt-slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: var(--vt-slide-distance);
  animation:
    var(--vt-duration-exit) ease-in both vt-fade reverse,
    400ms ease-in-out both vt-slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: calc(var(--vt-slide-distance) * -1);
  animation:
    var(--vt-duration-enter) ease-out var(--vt-duration-exit) both vt-fade,
    400ms ease-in-out both vt-slide;
}

/* Suspense: skeleton out → content in */
@keyframes vt-skeleton-fade {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes vt-skeleton-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes vt-skeleton-slide-y-out {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(8px);
  }
}

@keyframes vt-skeleton-slide-y-in {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

::view-transition-old(.skeleton-exit) {
  animation:
    var(--vt-duration-exit) ease-out both vt-skeleton-fade,
    var(--vt-duration-exit) ease-out both vt-skeleton-slide-y-out;
}

::view-transition-new(.skeleton-enter) {
  animation:
    var(--vt-duration-enter) ease-in var(--vt-duration-exit) both
      vt-skeleton-fade-in,
    400ms ease-in var(--vt-duration-exit) both vt-skeleton-slide-y-in;
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-image,
  .skeleton-text {
    animation: none;
  }

  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }
}

